import { createClient } from 'npm:@supabase/supabase-js@2.116.0'
const cors={"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"authorization, x-client-info, apikey, content-type","Access-Control-Allow-Methods":"POST,OPTIONS"}
Deno.serve(async(req)=>{if(req.method==='OPTIONS')return new Response('ok',{headers:cors});try{const auth=req.headers.get('Authorization');if(!auth)throw new Error('Unauthorized');const client=createClient(Deno.env.get('SUPABASE_URL')!,Deno.env.get('SUPABASE_PUBLISHABLE_KEY')!,{global:{headers:{Authorization:auth}}});const token=auth.replace(/^Bearer\s+/,'');const{data:{user},error}=await client.auth.getUser(token);if(error||!user)throw new Error('Unauthorized');const{other_user_id}=await req.json();if(typeof other_user_id!=='string'||other_user_id===user.id)throw new Error('Invalid user');const admin=createClient(Deno.env.get('SUPABASE_URL')!,Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);const{data:match}=await admin.from('matches').select('id').or(`and(user_a.eq.${user.id},user_b.eq.${other_user_id}),and(user_a.eq.${other_user_id},user_b.eq.${user.id})`).maybeSingle();if(!match)throw new Error('You must match before messaging');const{data:blocked}=await admin.from('blocks').select('id').or(`and(blocker_id.eq.${user.id},blocked_id.eq.${other_user_id}),and(blocker_id.eq.${other_user_id},blocked_id.eq.${user.id})`).limit(1);if(blocked?.length)throw new Error('Blocked');const a=user.id<other_user_id?user.id:other_user_id,b=user.id<other_user_id?other_user_id:user.id;const{data:c,error:ce}=await admin.from('conversations').upsert({user_a:a,user_b:b},{onConflict:'user_a,user_b'}).select('id,user_a,user_b,created_at').single();if(ce)throw ce;return new Response(JSON.stringify({conversation:c}),{headers:{...cors,'Content-Type':'application/json'}})}catch(e){return new Response(JSON.stringify({error:e instanceof Error?e.message:'Request failed'}),{status:400,headers:{...cors,'Content-Type':'application/json'}})}})
